//! `zigo-gen publish`: copies the generated tree into the package's source
//! directory and removes the generated files a previous run left behind.
//!
//! `UpdateSourceFiles` copies a named list of files, which this cannot be: how
//! many files a binding produces depends on what the binding declares, and
//! only the generator knows that. Pruning is part of the same job -- a file
//! left over from a binding that no longer produces it is exactly what
//! `zigo check` reports as obsolete, so a publish that did not prune would
//! leave the tree failing its own check.
const std = @import("std");
const go_walk = @import("go_walk.zig");
const output_manifest = @import("output_manifest");

const generated_marker = "// Code generated by zigo. DO NOT EDIT.";
/// Written by `cgo-link-flags`, outside the manifest, so pruning leaves it.
pub const volatile_cgo_link_file = "zigo_link_inputs_gen.go";

pub fn publish(allocator: std.mem.Allocator, io: std.Io, generated_path: []const u8, source_path: []const u8) !void {
    const cwd = std.Io.Dir.cwd();
    var generated_dir = try cwd.openDir(io, generated_path, .{ .iterate = true });
    defer generated_dir.close(io);
    try cwd.createDirPath(io, source_path);
    var source = try cwd.openDir(io, source_path, .{ .iterate = true });
    defer source.close(io);

    const current = try output_manifest.read(allocator, io, generated_dir);
    defer if (current) |value| value.deinit();
    const previous = try output_manifest.read(allocator, io, source);
    defer if (previous) |value| value.deinit();
    var published: std.ArrayList([]const u8) = .empty;
    defer published.deinit(allocator);
    if (current) |manifest| {
        for (manifest.value.files) |file| {
            if (file.publishable()) try published.append(allocator, file.path);
        }
    } else {
        var walker = try go_walk.walk(generated_dir, allocator);
        defer walker.deinit();
        while (try walker.next(io)) |entry| {
            if (entry.kind == .file and std.mem.endsWith(u8, entry.path, ".go"))
                try published.append(allocator, try allocator.dupe(u8, entry.path));
        }
    }
    for (published.items) |sub_path| {
        if (std.fs.path.dirname(sub_path)) |dirname| try source.createDirPath(io, dirname);
        _ = try std.Io.Dir.updateFile(generated_dir, io, sub_path, source, sub_path, .{});
    }

    // Exact artifacts do not carry a marker; their previous manifest is
    // the ownership record. Only obsolete publishable entries are pruned.
    if (previous) |manifest| for (manifest.value.files) |file| {
        if (!file.publishable()) continue;
        for (published.items) |path| {
            if (go_walk.eqlPath(file.path, path)) break;
        } else {
            source.deleteFile(io, file.path) catch |err| switch (err) {
                error.FileNotFound => continue,
                else => return err,
            };
        }
    };
    var stale_walker = try go_walk.walk(source, allocator);
    defer stale_walker.deinit();
    while (try stale_walker.next(io)) |entry| {
        if (entry.kind != .file or !std.mem.endsWith(u8, entry.path, ".go")) continue;
        for (published.items) |sub_path| {
            if (go_walk.eqlPath(sub_path, entry.path)) break;
        } else {
            if (std.mem.eql(u8, std.fs.path.basename(entry.path), volatile_cgo_link_file)) continue;
            // Only zigo's own output is removed; anything the user wrote in
            // the same directory carries no marker and is left alone.
            const contents = source.readFileAlloc(io, entry.path, allocator, .limited(64 * 1024 * 1024)) catch continue;
            defer allocator.free(contents);
            if (!std.mem.startsWith(u8, contents, generated_marker)) continue;
            try source.deleteFile(io, entry.path);
        }
    }

    if (current != null) _ = try generated_dir.updateFile(io, output_manifest.filename, source, output_manifest.filename, .{});
}
